mapper.select:
SELECT COUNT(*) FROM user_coupon u
WHERE u.username=#{username}
AND u.status=#{status}

SELECT u.*, p.code, p.label, p.min_yuan, p.off_yuan, p.expire_at AS promo_expire
FROM user_coupon u JOIN promo_coupon p ON p.id=u.coupon_id
WHERE u.username=#{username}
AND u.status=#{status}
ORDER BY u.id DESC

SELECT u.*, p.code, p.label, p.min_yuan, p.off_yuan, p.expire_at AS promo_expire
FROM user_coupon u JOIN promo_coupon p ON p.id=u.coupon_id
WHERE u.username=#{username} AND u.coupon_id=#{couponId}

SELECT u.id AS user_coupon_id, p.*
FROM user_coupon u JOIN promo_coupon p ON p.id=u.coupon_id
WHERE u.username=#{username} AND u.status='unused' AND UPPER(p.code)=#{code}

SELECT u.id FROM user_coupon u JOIN promo_coupon p ON p.id=u.coupon_id
WHERE u.username=#{username} AND u.status='unused' AND UPPER(p.code)=#{code}
LIMIT 1
